}
function addMuzzleLight(position) {
  const l = new THREE.PointLight(0xffb05a, 5, 7, 2); l.position.copy(position); scene.add(l);
  state.effects.push({ kind: 'light', obj: l, life: .06, maxLife: .06 });
}
function addDustBurst(pos) {
