    } else {
      dest = bot.roleSpot;
    }
    if (dest) {
      if (bot.pos.distanceTo(dest) > 1.4) { pathTo(bot, dest); moveSpeed = followPath(bot, dt); }
      else { bot.yaw = lerpAngle(bot.yaw, state.phase === 'freeze' ? bot.yaw : (bot.team === 't' ? Math.PI : 0), dt * 2); }
    }
